// Shake → replay → regression spec → run it. Uses the real SDK inside the real app: the scenario's steps are
// played in Chromium, then window.ShakeFix.getReplay(note) returns the replay the SDK recorded, exactly
// what a shake would send. The spec is generated by packages/replay (the same generator the Triage Nurse
// uses as its starting point).
import { mkdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { join, relative } from 'node:path';
import { runFlow } from '../../packages/replay/lib/flow-runner.js';
import { generateSpec } from '../../packages/replay/lib/to-spec.js';

export const CONTEXT = { viewport: { width: 390, height: 844 }, reducedMotion: 'reduce', timezoneId: 'UTC', locale: 'en-US' };

/** Adds `t` (ms) and `route` placeholders so the steps are a valid flow for the replay runner. */
export function stepsAsFlow(steps) {
  return {
    startRoute: steps.startRoute,
    actions: steps.actions.map((a, i) => ({ t: i * 400, route: steps.startRoute, selector: a.selector ?? `[data-testid="${a.testid}"]`, ...a })),
    expectation: null,
  };
}

/**
 * Plays the scenario on `baseUrl` and returns {replay, sdkExpectation, stepErrors}.
 * @param {import('@playwright/test').Browser} browser
 */
export async function produceReplay(browser, baseUrl, scenario) {
  const context = await browser.newContext({ ...CONTEXT, baseURL: baseUrl });
  const page = await context.newPage();
  try {
    const res = await runFlow(page, stepsAsFlow(scenario.steps), {
      baseURL: baseUrl,
      reset: true,
      stopOnError: false,
      timeout: 5000,
      onStart: () => page.waitForFunction(() => window.ShakeFix && window.ShakeFix.__live, null, { timeout: 10_000 }),
    });
    await page.waitForLoadState('networkidle', { timeout: 3000 }).catch(() => {});
    await page.waitForTimeout(300);
    const replay = await page.evaluate((note) => window.ShakeFix.getReplay(note), scenario.note);
    replay.trigger = 'shake';
    if (Array.isArray(scenario.plantedConsole)) replay.console = [...(replay.console ?? []), ...scenario.plantedConsole];
    return { replay, sdkExpectation: replay.expectation ?? null, stepErrors: res.errors };
  } finally {
    await context.close().catch(() => {});
  }
}

/**
 * Regression spec(s) for a replay. `repro` uses the scenario's expectation when the SDK could not infer one
 * (or inferred a different one); `sdk-only` is the replay exactly as the SDK sent it.
 * @returns {{repro: string, sdkOnly: string|null, expectationSource: 'sdk'|'scenario'|'none'}}
 */
export function writeSpecs(dir, scenario, replay, iid) {
  mkdirSync(dir, { recursive: true });
  const sdkExp = replay.expectation ?? null;
  const exp = scenario.expectation ?? sdkExp;
  const expectationSource = scenario.expectation ? 'scenario' : sdkExp ? 'sdk' : 'none';
  const repro = join(dir, 'repro.spec.ts');
  writeFileSync(repro, generateSpec({ ...replay, expectation: exp }, { iid }));
  writeFileSync(join(dir, 'replay.json'), `${JSON.stringify(replay, null, 2)}\n`);
  let sdkOnly = null;
  if (JSON.stringify(exp) !== JSON.stringify(sdkExp)) {
    sdkOnly = join(dir, 'sdk-only.spec.ts');
    writeFileSync(sdkOnly, generateSpec(replay, { iid }));
  }
  return { repro, sdkOnly, expectationSource };
}

function collect(suite, out) {
  for (const s of suite.suites ?? []) collect(s, out);
  for (const spec of suite.specs ?? []) {
    const statuses = (spec.tests ?? []).flatMap((t) => (t.results ?? []).map((r) => r.status));
    const file = spec.file ?? suite.file;
    const first = (spec.tests ?? []).flatMap((t) => t.results ?? []).find((r) => r.error)?.error?.message ?? null;
    out.push({ file, status: statuses.every((x) => x === 'passed') && statuses.length ? 'passed' : statuses[0] ?? 'unknown', error: first });
  }
  return out;
}

/**
 * Runs every *.spec.ts under `dir` against `baseUrl`. Returns {<basename>: {status, error}}.
 */
export function runSpecs({ repoRoot, dir, baseUrl, files }) {
  const report = join(dir, `report-${Date.now()}.json`);
  const cli = join(repoRoot, 'node_modules', '@playwright', 'test', 'cli.js');
  const args = [cli, 'test', '--config', join(repoRoot, 'evals', 'playwright.eval.config.mjs'), ...(files ?? []).map((f) => relative(dir, f).split('\\').join('/'))];
  const r = spawnSync(process.execPath, args, {
    cwd: repoRoot,
    env: { ...process.env, BASE_URL: baseUrl, EVAL_SPEC_DIR: dir, EVAL_REPORT: report, CI: '' },
    encoding: 'utf8',
    timeout: 180_000,
  });
  if (!existsSync(report)) throw new Error(`playwright produced no report (exit ${r.status}): ${(r.stderr || r.stdout || '').slice(-1500)}`);
  const json = JSON.parse(readFileSync(report, 'utf8'));
  const out = {};
  for (const row of collect({ suites: json.suites ?? [] }, [])) {
    const name = String(row.file ?? '').split(/[\\/]/).pop();
    out[name] = { status: row.status, error: row.error ? String(row.error).split('\n')[0].replace(/\u001b\[[0-9;]*m/g, '').slice(0, 200) : null };
  }
  return out;
}
